#!/usr/bin/env bash
# Builds the Arch Linux package and a matching binary PKGBUILD from the .deb
# that the Linux release build already produced, so Arch needs no separate
# container, rebuild or published tag.
#
# Usage: arch-package.sh <version> <deb-file> <out-dir>
set -euo pipefail

VERSION="$1"
DEB="$2"
OUT="$3"
PKGNAME=google-chat-desktop
REPO_URL=https://github.com/madratzz/tauri-google-chat
# Name GitHub gives the uploaded .deb asset (spaces in the bundle name become dots).
DEB_ASSET="Google.Chat.Desktop_${VERSION}_amd64.deb"

mkdir -p "$OUT"
OUT="$(cd "$OUT" && pwd)"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

# 1. Package contents = the .deb payload (binary, .desktop file, icons).
STAGING="$WORK/pkg"
mkdir -p "$STAGING"
dpkg-deb -x "$DEB" "$STAGING"
test -x "$STAGING/usr/bin/$PKGNAME"

SIZE=$(du -sk "$STAGING" | awk '{print $1 * 1024}')
cat > "$STAGING/.PKGINFO" <<EOF
pkgname = $PKGNAME
pkgbase = $PKGNAME
pkgver = ${VERSION}-1
pkgdesc = A Tauri desktop wrapper for Google Chat
url = $REPO_URL
builddate = $(date +%s)
packager = GitHub Actions
size = $SIZE
arch = x86_64
license = MIT
depend = webkit2gtk-4.1
depend = gtk3
depend = libayatana-appindicator
EOF

PKGFILE="$OUT/${PKGNAME}-${VERSION}-1-x86_64.pkg.tar.zst"
(cd "$STAGING" && LC_ALL=C tar --zstd --owner=0 --group=0 --numeric-owner \
  -cf "$PKGFILE" .PKGINFO usr)

# 2. Binary PKGBUILD that repackages the released .deb (checksum known now,
#    no dependency on the source tarball of an unpublished tag).
SHA=$(sha256sum "$DEB" | cut -d' ' -f1)
cat > "$OUT/PKGBUILD" <<EOF
# Maintainer: madratzz
# Generated by .github/scripts/arch-package.sh for the v${VERSION} release.
pkgname=$PKGNAME
pkgver=$VERSION
pkgrel=1
pkgdesc='A Tauri desktop wrapper for Google Chat'
arch=('x86_64')
url='$REPO_URL'
license=('MIT')
depends=('webkit2gtk-4.1' 'gtk3' 'libayatana-appindicator')
source=("\$pkgname-\$pkgver.deb::$REPO_URL/releases/download/v\$pkgver/$DEB_ASSET")
noextract=("\$pkgname-\$pkgver.deb")
sha256sums=('$SHA')

package() {
    bsdtar -xOf "\$pkgname-\$pkgver.deb" 'data.tar.*' | bsdtar -xf - -C "\$pkgdir"
}
EOF

echo "Built $PKGFILE"
echo "Built $OUT/PKGBUILD"
